/**
 * Token-economy baseline contract (Residual F / §6 metric #3).
 *
 * Measures Layer-0 (distilled summary) size vs the raw result size across the 3
 * representative spike fixtures, and locks the ratios against a committed baseline.
 *
 * Proxy: character count via stableJson().length. The repo has no tokenizer, and
 * all budgets are char-based (SUMMARY_BUDGET_CHARS etc.), so chars are the
 * established, deterministic proxy (same one check-token-contract.mjs uses).
 *
 * Determinism: fixtures are generated by fixed index-based loops (no Date/random),
 * and each raw payload is kept under the 8KB artifact-save threshold so NO artifact
 * is written and the emitted envelope.summary is fully reproducible. Layer-0 is
 * measured as stableJson(envelope.summary) — the structured summary core, free of
 * volatile artifact paths.
 *
 * n=3 is a guardrail, not statistics: "median" is the middle fixture, and we also
 * report max. The hard invariant (§6 "Layer 0 必须下降") is layer0 < raw per fixture.
 *
 * Regenerate the committed baseline deliberately with:  npm run check:token-economy -- --update
 */
import assert from "node:assert/strict";
import { readFileSync, writeFileSync, mkdtempSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { tmpdir } from "node:os";
import { stableJson } from "../../../src/utils/json.ts";
import { distilledJsonResult } from "../../../src/tools/resultMiddleware.ts";

const here = path.dirname(fileURLToPath(import.meta.url));
const baselinePath = path.join(here, "fixtures", "token-economy-baseline.json");
const UPDATE = process.argv.includes("--update");
const TOLERANCE = 0.1; // ±10% drift allowed on the distilled size before regression

// ── Deterministic fixtures (fixed loops; raw kept < 8KB → no artifact write) ──

function evidenceFixture() {
	const sources = {};
	for (let i = 0; i < 6; i++) {
		sources[`source_${i}`] = { ok: true, data: { events: Array.from({ length: 4 }, (_, j) => ({ type: `evt_${i % 3}`, seq: j })), items: [{ tag: "DIV", idx: i }] } };
	}
	return { tabId: 1, collected_at: "2026-06-01T00:00:00Z", event_types: ["console", "network"], sources };
}

function networkFixture() {
	const entries = Array.from({ length: 45 }, (_, i) => ({
		requestId: String(i),
		url: `https://host${i % 3}.example.test/api/resource/${i}`,
		method: i % 4 === 0 ? "POST" : "GET",
		status: i % 9 === 0 ? 500 : i % 5 === 0 ? 404 : 200,
		type: "Fetch",
	}));
	return { tabId: 7, sessionId: "tok-econ", total: entries.length, entries };
}

function hookFixture() {
	const listeners = Array.from({ length: 20 }, (_, i) => ({
		type: ["click", "submit", "input", "change"][i % 4],
		useCapture: i % 2 === 0,
		passive: false,
		once: false,
		handler: { url: `https://h${i % 3}.test/a.js`, line: 100 + i, column: i % 40, functionName: `fn_${i % 5}` },
	}));
	return { selector: "#root", node: { tagName: "DIV", id: "root" }, count: listeners.length, listeners };
}

const FIXTURES = [
	{ name: "browser_evidence", command: "evidence.collect", value: evidenceFixture() },
	{ name: "browser_network", command: "network.list", value: networkFixture() },
	{ name: "browser_hook", command: "hook.getNodeListeners", value: hookFixture() },
];

// ── Measure ───────────────────────────────────────────────────────────────────

const ctxDir = mkdtempSync(path.join(tmpdir(), "tok-econ-"));

async function measure(fx) {
	const rawChars = stableJson(fx.value).length;
	const r = await distilledJsonResult(fx.value, {
		toolName: fx.name, command: fx.command, maxChars: 12000, fallbackName: `${fx.name}.json`,
		detailLevel: "summary", ctx: { cwd: ctxDir },
	});
	const envelope = JSON.parse(r.content[0].text);
	// Sanity: a sub-8KB raw must not have triggered an artifact write (keeps it deterministic).
	assert(!envelope.saved, `${fx.name}: fixture must stay under the artifact-save threshold for a deterministic measurement`);
	const layer0Chars = stableJson(envelope.summary).length;
	return { name: fx.name, rawChars, layer0Chars, ratio: Number((layer0Chars / rawChars).toFixed(4)) };
}

const results = [];
for (const fx of FIXTURES) results.push(await measure(fx));

const ratios = results.map((r) => r.ratio).sort((a, b) => a - b);
const medianRatio = ratios[Math.floor(ratios.length / 2)];
const maxRatio = ratios[ratios.length - 1];

// ── Hard invariant: Layer 0 must be smaller than raw (§6) ─────────────────────

for (const r of results) {
	assert(r.layer0Chars < r.rawChars, `${r.name}: Layer-0 (${r.layer0Chars}) must be smaller than raw (${r.rawChars})`);
}

// ── Baseline: update or assert non-regression ─────────────────────────────────

const current = { proxy: "chars/stableJson", note: "n=3 guardrail; layer0 = stableJson(envelope.summary)", fixtures: results, medianRatio, maxRatio };

if (UPDATE) {
	writeFileSync(baselinePath, `${JSON.stringify(current, null, 2)}\n`, "utf8");
	console.log("token economy baseline UPDATED:", JSON.stringify({ medianRatio, maxRatio }));
} else {
	let baseline;
	try {
		baseline = JSON.parse(readFileSync(baselinePath, "utf8"));
	} catch {
		assert.fail("token-economy-baseline.json missing — run: npm run check:token-economy -- --update");
	}
	for (const r of results) {
		const b = baseline.fixtures.find((x) => x.name === r.name);
		assert(b, `baseline missing fixture ${r.name} — regenerate with --update`);
		assert.equal(r.rawChars, b.rawChars, `${r.name}: rawChars drifted (${r.rawChars} vs baseline ${b.rawChars}) — fixtures changed; regenerate with --update`);
		assert(r.layer0Chars <= Math.ceil(b.layer0Chars * (1 + TOLERANCE)), `${r.name}: Layer-0 grew beyond +${TOLERANCE * 100}% (${r.layer0Chars} vs baseline ${b.layer0Chars}) — investigate or regenerate with --update`);
	}
	console.log(`token economy ok (medianRatio=${medianRatio}, maxRatio=${maxRatio})`);
}
